using Clock = std::chrono::steady_clock;
int main(int argc,char** argv) {
    try {
        if(argc!=5)throw std::runtime_error("usage: placement-model MODEL TOKENS OUTPUT scheduler|fixed");
        const std::string_view mode(argv[4]);
        if(mode!="scheduler" && mode!="fixed")throw std::runtime_error("invalid placement mode");
        auto weights=gguf::read_gguf(argv[1]);
        auto cpu=std::make_shared<backend::CpuBackend>();
        infer::Model model(weights,cpu);model.set_threads(6);model.set_ubatch(128);
        std::ifstream input(argv[2]); std::vector<uint32_t> ids; uint32_t id;
        while(input>>id)ids.push_back(id);
        if(!input.eof() || ids.size()!=247 || cpu->threads_available()!=6)throw std::runtime_error("invalid token input or thread count");
        std::vector<uint32_t> prompt(ids.begin(),ids.begin()+215);
        placement::Session session(*cpu,mode=="fixed");
        std::vector<float> warmup,final;
        struct Record {double pp,tg;uint64_t hash;};Record records[2]{};
        session.apply();session.verify();
        const std::string placement_before=session.json();
        for(int run=0;run<2;++run) {
            model.reset();
            auto start=Clock::now();auto logits=model.prefill(prompt);auto pp_end=Clock::now();
            for(size_t i=215;i<ids.size();++i)logits=model.step(ids[i]);
            auto tg_end=Clock::now();
            records[run].pp=std::chrono::duration<double,std::milli>(pp_end-start).count();
            records[run].tg=std::chrono::duration<double,std::milli>(tg_end-pp_end).count();
            uint64_t hash=14695981039346656037ull;
            for(float value:logits) {
                if(!std::isfinite(value))throw std::runtime_error("nonfinite final logit");
                uint32_t bits;std::memcpy(&bits,&value,4);
                for(int shift=0;shift<32;shift+=8){hash^=(bits>>shift)&255;hash*=1099511628211ull;}
            }
            records[run].hash=hash;
            if(!run)warmup=logits;
            else {
                if(logits.size()!=warmup.size() || std::memcmp(logits.data(),warmup.data(),logits.size()*4))
                    throw std::runtime_error("warmup/final vector differs");
                final=std::move(logits);
            }
        }
        session.verify();
        const std::string placement_after=session.json();
        session.restore();
        std::ofstream output(argv[3],std::ios::binary);output.exceptions(std::ios::badbit|std::ios::failbit);
        output.write(reinterpret_cast<const char*>(final.data()),std::streamsize(final.size()*sizeof(float)));output.close();
        std::cout<<std::setprecision(15)<<"{\"caller_thread_id\":"<<GetCurrentThreadId()<<",\"threads\":6,\"ubatch\":128,\"pp_tokens\":215,\"tg_tokens\":32,\"vocab\":"<<final.size()<<",\"placement\":"<<"{\"before\":"<<placement_before<<",\"after\":"<<placement_after<<",\"restored\":"<<session.json()<<"},\"records\":[";
        for(int i=0;i<2;++i){if(i)std::cout<<',';std::cout<<"{\"run\":"<<i<<",\"pp_ms\":"<<records[i].pp<<",\"tg_ms\":"<<records[i].tg<<",\"final_fnv64\":\""<<std::hex<<records[i].hash<<std::dec<<"\"}";}
        std::cout<<"]}\n";
    }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}

