namespace placement {
class Session {
    struct Core { DWORD_PTR mask; BYTE flags; BYTE efficiency; };
    struct Worker {
        DWORD id = 0;
        DWORD_PTR old_mask = 0, target = 0, applied_return = 0;
        DWORD_PTR current_mask = 0, restore_return = 0;
        DWORD_PTR applied_mask = 0, verified_mask = 0;
        unsigned verified_active = 0;
        WORD group = 0, applied_group = 0, verified_group = 0;
        BYTE processor = 0, applied_processor = 0, verified_processor = 0;
        bool captured = false, changed = false, restored = false, injected = false;
    };
    backend::CpuBackend& cpu_;
    bool fixed_, started_ = false, restored_ = false;
    DWORD caller_;
    DWORD_PTR allowed_ = 0, system_ = 0;
    std::vector<Core> cores_;
    std::array<Worker, 6> workers_{};

    static void require(bool ok, const char* text) {
        if (!ok) throw std::runtime_error(text);
    }
    static void wincheck(BOOL ok, const char* text) {
        if (!ok) throw std::runtime_error(std::string(text) + ": " + std::to_string(GetLastError()));
    }
    static unsigned lowest(DWORD_PTR mask) {
        unsigned bit = 0;
        while (!(mask & (DWORD_PTR(1) << bit))) ++bit;
        return bit;
    }
    void owner() const {
        require(cpu_.threads_available() == 6, "placement requires six unchanged participants");
        require(GetCurrentThreadId() == caller_, "placement caller changed");
    }
    static void observe(Worker& w) {
        require(GetCurrentThreadId() == w.id, "placement worker identity changed");
        GROUP_AFFINITY affinity{};
        wincheck(GetThreadGroupAffinity(GetCurrentThread(), &affinity), "GetThreadGroupAffinity");
        require(affinity.Group == 0, "placement thread group is not zero");
        w.current_mask = affinity.Mask;
        PROCESSOR_NUMBER processor{};
        GetCurrentProcessorNumberEx(&processor);
        w.group = processor.Group;
        w.processor = processor.Number;
    }
public:
    Session(backend::CpuBackend& cpu, bool fixed) : cpu_(cpu), fixed_(fixed), caller_(GetCurrentThreadId()) {
        owner();
        require(GetActiveProcessorGroupCount() == 1, "placement requires a single processor group");
        wincheck(GetProcessAffinityMask(GetCurrentProcess(), &allowed_, &system_), "GetProcessAffinityMask");
        require(allowed_ != 0, "placement process mask is empty");
        DWORD bytes = 0;
        BOOL ok = GetLogicalProcessorInformationEx(RelationProcessorCore, nullptr, &bytes);
        require(!ok && GetLastError() == ERROR_INSUFFICIENT_BUFFER && bytes != 0, "topology size query failed");
        std::vector<unsigned char> storage(bytes);
        wincheck(GetLogicalProcessorInformationEx(RelationProcessorCore,
            reinterpret_cast<PSYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX>(storage.data()), &bytes), "topology query");
        DWORD_PTR seen = 0;
        for (size_t offset = 0; offset < bytes;) {
            require(bytes - offset >= 8, "truncated topology record");
            auto* info = reinterpret_cast<PSYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX>(storage.data() + offset);
            require(info->Size >= offsetof(SYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX, Processor.GroupMask) + sizeof(GROUP_AFFINITY)
                && info->Size <= bytes - offset && info->Relationship == RelationProcessorCore, "invalid topology record");
            const auto& core = info->Processor;
            require(core.GroupCount == 1 && core.GroupMask[0].Group == 0, "unsupported core group");
            DWORD_PTR mask = core.GroupMask[0].Mask;
            require(mask != 0 && !(seen & mask), "overlapping or empty core topology");
            seen |= mask;
            cores_.push_back({mask, core.Flags, core.EfficiencyClass});
            offset += info->Size;
        }
        require((allowed_ & ~seen) == 0, "allowed processor missing from topology");
        std::vector<DWORD_PTR> eligible;
        for (const auto& core : cores_) if (core.mask & allowed_) eligible.push_back(core.mask & allowed_);
        std::sort(eligible.begin(), eligible.end(), [](DWORD_PTR a, DWORD_PTR b) { return lowest(a) < lowest(b); });
        require(eligible.size() >= workers_.size(), "fewer than six allowed physical cores");
        for (size_t i = 0; i < workers_.size(); ++i) workers_[i].target = DWORD_PTR(1) << lowest(eligible[i]);
    }
    Session(const Session&) = delete;
    Session& operator=(const Session&) = delete;
    ~Session() noexcept { if (started_ && !restored_) { try { restore(); } catch (...) {} } }

    void apply(int fail_worker = -1) {
        owner();
        require(!started_, "placement session already applied");
        require(fail_worker >= -1 && fail_worker < 6, "invalid failure worker");
        started_ = true;
        try {
            cpu_.run_parallel([&](int index) {
                auto& w = workers_[size_t(index)];
                w.id = GetCurrentThreadId();
                observe(w);
                w.old_mask = w.current_mask;
                w.captured = true;
                if (fixed_) {
                    w.applied_return = SetThreadAffinityMask(GetCurrentThread(), w.target);
                    wincheck(w.applied_return != 0, "SetThreadAffinityMask apply");
                    w.changed = true;
                    require(w.applied_return == w.old_mask, "prior thread mask changed during apply");
                }
                observe(w);
                w.applied_mask = w.current_mask;
                w.applied_group = w.group;
                w.applied_processor = w.processor;
                if (index == fail_worker) {
                    w.injected = true;
                    throw std::runtime_error("injected placement failure");
                }
            });
            verify();
        } catch (...) {
            auto failure = std::current_exception();
            try { restore(); }
            catch (const std::exception& e) { throw std::runtime_error(std::string("placement apply failed; cleanup failed: ") + e.what()); }
            std::rethrow_exception(failure);
        }
    }
    void verify() {
        owner();
        require(started_, "placement session not applied");
        cpu_.run_parallel([&](int index) {
            auto& w = workers_[size_t(index)];
            require(w.captured, "placement worker was not captured");
            observe(w);
            const DWORD_PTR expected = fixed_ && !restored_ ? w.target : w.old_mask;
            require(w.current_mask == expected, "placement mask witness mismatch");
            require(w.group == 0 && w.processor < sizeof(DWORD_PTR) * 8
                && (expected & (DWORD_PTR(1) << w.processor)), "placement processor witness mismatch");
            if (!restored_) {
                ++w.verified_active;
                w.verified_mask = w.current_mask;
                w.verified_group = w.group;
                w.verified_processor = w.processor;
            }
        });
    }
    void restore() {
        owner();
        if (!started_) return;
        cpu_.run_parallel([&](int index) {
            auto& w = workers_[size_t(index)];
            if (!w.captured) return;
            require(GetCurrentThreadId() == w.id, "placement worker identity changed during restore");
            if (w.changed) {
                w.restore_return = SetThreadAffinityMask(GetCurrentThread(), w.old_mask);
                wincheck(w.restore_return != 0, "SetThreadAffinityMask restore");
                w.changed = false;
            }
            observe(w);
            require(w.current_mask == w.old_mask, "restored mask mismatch");
            w.restored = true;
        });
        restored_ = true;
    }
    std::string json() const {
        std::ostringstream out;
        out << "{\"mode\":\"" << (fixed_ ? "fixed" : "unbound") << "\",\"process_mask\":" << allowed_
            << ",\"system_mask\":" << system_ << ",\"restored\":" << (restored_ ? "true" : "false") << ",\"topology\":[";
        for (size_t i = 0; i < cores_.size(); ++i) {
            if (i) out << ',';
            out << "{\"group\":0,\"mask\":" << cores_[i].mask << ",\"flags\":" << unsigned(cores_[i].flags)
                << ",\"efficiency_class\":" << unsigned(cores_[i].efficiency) << '}';
        }
        out << "],\"workers\":[";
        for (size_t i = 0; i < workers_.size(); ++i) {
            if (i) out << ',';
            const auto& w = workers_[i];
            out << "{\"worker\":" << i << ",\"thread_id\":" << w.id << ",\"old_mask\":" << w.old_mask
                << ",\"target_mask\":" << w.target << ",\"applied_return\":" << w.applied_return
                << ",\"applied_mask\":" << w.applied_mask << ",\"applied_group\":" << w.applied_group
                << ",\"applied_cpu\":" << unsigned(w.applied_processor) << ",\"verified_active\":" << w.verified_active
                << ",\"verified_mask\":" << w.verified_mask << ",\"verified_group\":" << w.verified_group
                << ",\"verified_cpu\":" << unsigned(w.verified_processor)
                << ",\"current_mask\":" << w.current_mask << ",\"restore_return\":" << w.restore_return
                << ",\"observed_group\":" << w.group << ",\"observed_cpu\":" << unsigned(w.processor)
                << ",\"captured\":" << (w.captured ? "true" : "false") << ",\"changed\":" << (w.changed ? "true" : "false")
                << ",\"restored\":" << (w.restored ? "true" : "false") << ",\"injected\":" << (w.injected ? "true" : "false") << '}';
        }
        out << "]}";
        return out.str();
    }
};
